'use strict';
/* REGUL ARENA — Pack Prudentiel/Bâle (QB) enrichi expl+exemple — Phase B. Validé Amadou Sall avant prod. */
const QB = [
{"cat":"Fonds propres","q":"Quel est le ratio minimum de fonds propres de base de catégorie 1 (CET1) exigé des établissements de crédit de l'UMOA ?","choices":["4,5% des risques pondérés","5% des risques pondérés","6% des risques pondérés","8% des risques pondérés"],"answer":1,"source":"Avis n°004-04-2016 BCEAO — Art. 24 (Titre III)","expl":"Le CET1 (fonds propres de base durs) doit atteindre au minimum 5% des risques pondérés (APR) dans l'UMOA.","exemple":"Une banque avec 500 Mds FCFA d'APR doit détenir au moins 25 Mds de CET1."},
{"cat":"Fonds propres","q":"Quel est le ratio minimum de fonds propres de catégorie 1 (Tier 1 = CET1 + AT1) ?","choices":["5%","6%","7,5%","8%"],"answer":1,"source":"Décision 013/2016 CM/UMOA — Annexe Titre III §103","expl":"Le Tier 1 (CET1 + AT1) doit représenter au minimum 6% des APR.","exemple":"Au-delà des 5% de CET1, la banque peut compléter jusqu'à 6% via des instruments AT1 éligibles."},
{"cat":"Fonds propres","q":"Quel est le ratio minimum de fonds propres effectifs (FPE = T1 + T2) hors coussins ?","choices":["7%","8%","10,5%","12%"],"answer":1,"source":"Décision 013/2016 CM/UMOA — Annexe §103","expl":"Les fonds propres effectifs (T1 + T2), hors coussins, doivent représenter au moins 8% des APR — le socle dur de solvabilité.","exemple":"Pour 500 Mds d'APR, il faut au moins 40 Mds de fonds propres effectifs avant coussins."},
{"cat":"Fonds propres","q":"Quel est le niveau du coussin de conservation des fonds propres en cible 2022 ?","choices":["1,25%","1,875%","2,5%","3%"],"answer":2,"source":"Décision 013/2016 CM/UMOA — Annexe Titre III (Coussin de conservation)","expl":"Le coussin de conservation cible (2022) est de 2,5% des APR, constitué de CET1, au-dessus des minima.","exemple":"Entamer ce coussin déclenche des restrictions de distribution (dividendes, primes)."},
{"cat":"Fonds propres","q":"Le coussin contracyclique imposable par la BCEAO peut atteindre quel niveau maximum ?","choices":["1%","1,5%","2,5%","5%"],"answer":2,"source":"Décision 013/2016 CM/UMOA — Annexe (Coussin contracyclique)","expl":"La BCEAO peut imposer un coussin contracyclique allant jusqu'à 2,5% des APR pour tempérer une expansion excessive du crédit.","exemple":"En période de surchauffe du crédit, la BCEAO relève ce coussin, obligeant les banques à renforcer leurs fonds propres."},
{"cat":"Fonds propres","q":"Quel est le total des exigences minimales en fonds propres (FPE + coussin de conservation) à horizon 2022 ?","choices":["8%","9,5%","10,5%","12,5%"],"answer":2,"source":"Décision 013/2016 CM/UMOA — Annexe Titre III (cible pleine 2022)","expl":"FPE (8%) + coussin de conservation (2,5%) = exigence pleine de 10,5% des APR à horizon 2022.","exemple":"Sous 10,5%, la banque subit des restrictions de distribution même si elle respecte les 8% durs."},
{"cat":"Fonds propres","q":"Quelles sont les trois grandes composantes des fonds propres effectifs (FPE) au sens du dispositif prudentiel UMOA ?","choices":["Capital + Réserves + Provisions","CET1 + AT1 + T2","Tier 1 + Tier 2 + Tier 3","Fonds propres durs + Quasi-fonds propres + Dettes subordonnées"],"answer":1,"source":"Annexe Décision 013/2016 — §12 (Composantes des fonds propres)","expl":"Les fonds propres effectifs se composent de trois briques hiérarchisées par qualité : CET1, AT1 et T2.","exemple":"Pour un calcul de solvabilité, on additionne CET1 + AT1 + T2 au numérateur du ratio."},
{"cat":"Fonds propres","q":"Que représentent les fonds propres de base durs (CET1) dans la structure des fonds propres ?","choices":["Les fonds propres de qualité moyenne","Les fonds propres de meilleure qualité permettant la continuité d'exploitation","Les fonds propres absorbant les pertes uniquement en liquidation","Les fonds propres remboursables à court terme"],"answer":1,"source":"Annexe Décision 013/2016 — §11(a) (Définition CET1)","expl":"Le CET1 est le noyau dur : la meilleure qualité de fonds propres, capable d'absorber les pertes en continuité d'exploitation.","exemple":"En cas de pertes, c'est le CET1 qui les encaisse en premier, sans mettre la banque en liquidation."},
{"cat":"Fonds propres","q":"Quels éléments composent principalement le CET1 ?","choices":["Dettes subordonnées et obligations convertibles","Capital social libéré (actions ordinaires), primes d'émission, report à nouveau créditeur, réserve spéciale, réserves statutaires","Provisions générales et plus-values latentes","Comptes courants d'associés et avances en compte"],"answer":1,"source":"Annexe Décision 013/2016 — §15 (Éléments composant le CET1)","expl":"Le CET1 regroupe le capital social libéré, les primes d'émission, le report à nouveau créditeur, la réserve spéciale et les réserves statutaires.","exemple":"Les bénéfices mis en réserve renforcent le CET1 et améliorent le ratio de solvabilité."},
{"cat":"Fonds propres","q":"Quel pourcentage des bénéfices nets annuels doit être affecté à la réserve spéciale obligatoire des banques UMOA ?","choices":["5%","10%","15%","20%"],"answer":2,"source":"Annexe Décision 013/2016 — §16 (Réserve spéciale, prélèvement 15%)","expl":"Les banques UMOA doivent affecter 15% de leurs bénéfices nets annuels à la réserve spéciale obligatoire.","exemple":"Sur un bénéfice net de 10 Mds, 1,5 Md est mis en réserve spéciale avant toute distribution."},
{"cat":"Fonds propres","q":"À partir de quel niveau de réserve spéciale la dotation cesse-t-elle d'être obligatoire ?","choices":["Lorsqu'elle atteint le dixième du capital social","Lorsqu'elle atteint le cinquième (20%) du montant du capital social, ET que les ratios cibles sont respectés","Lorsqu'elle atteint la moitié du capital social","Elle ne cesse jamais d'être obligatoire"],"answer":1,"source":"Annexe Décision 013/2016 — §16 (Conditions de cessation de dotation)","expl":"La dotation cesse d'être obligatoire quand la réserve spéciale atteint 20% (un cinquième) du capital social ET que les ratios cibles sont respectés.","exemple":"Réserve spéciale = 20% du capital et ratios OK : la banque n'est plus tenue d'y prélever 15%."},
{"cat":"Fonds propres","q":"Pour intégrer le bénéfice intermédiaire dans le CET1, quelle condition principale est requise ?","choices":["Décision de l'AG uniquement","Vérification par les commissaires aux comptes + déduction des charges et dividendes prévisibles","Approbation du Conseil d'Administration uniquement","Aucune vérification spécifique"],"answer":1,"source":"Annexe Décision 013/2016 — §18 (Conditions intégration du bénéfice)","expl":"Intégrer un bénéfice intermédiaire au CET1 suppose sa vérification par les commissaires aux comptes et la déduction des charges et dividendes prévisibles.","exemple":"Un résultat semestriel ne renforce le CET1 qu'après audit et retrait des dividendes attendus."},
{"cat":"Fonds propres","q":"Que sont les fonds propres de base additionnels (AT1) ?","choices":["Des fonds propres complémentaires de qualité supérieure au CET1","Une composante des fonds propres de base de qualité moindre que le CET1, mais stable pour absorber les pertes et permettre la continuité d'exploitation","Des dettes subordonnées sans capacité d'absorption","Des provisions générales pour risques bancaires"],"answer":1,"source":"Annexe Décision 013/2016 — §11(b) (Définition AT1)","expl":"Les AT1 sont des fonds propres de base de qualité moindre que le CET1 mais stables, absorbant les pertes en continuité d'exploitation.","exemple":"Une action de préférence perpétuelle éligible AT1 complète le CET1 pour atteindre le Tier 1 de 6%."},
{"cat":"Fonds propres","q":"Que représentent les fonds propres complémentaires (T2) ?","choices":["Des fonds propres équivalents au CET1","Des fonds propres de qualité moindre que les AT1 mais avec capacité d'absorption de pertes en cas de LIQUIDATION","Des dettes seniors classiques","Le report à nouveau créditeur uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — §11(c) (Définition T2)","expl":"Les T2 (complémentaires) sont d'une qualité inférieure aux AT1 : ils absorbent surtout les pertes en cas de liquidation.","exemple":"Une dette subordonnée à long terme éligible T2 renforce les FPE mais pas le noyau dur CET1."},
{"cat":"Fonds propres","q":"Pour les instruments AT1 et T2, quelle clause contractuelle est obligatoire ?","choices":["Aucune clause particulière","Clause de conversion intégrale et permanente en actions ordinaires OU annulation en cas de point de non-viabilité","Clause de remboursement anticipé garanti","Clause de paiement de dividendes prioritaires"],"answer":1,"source":"Annexe Décision 013/2016 — §13 (Clause de conversion au point de non-viabilité)","expl":"Les instruments AT1 et T2 doivent prévoir une conversion en actions ordinaires ou une annulation au point de non-viabilité.","exemple":"Au point de non-viabilité, l'instrument AT1 est converti ou annulé, absorbant la perte."},
{"cat":"Fonds propres","q":"Que désignent les « participations significatives » dans une autre entité financière ?","choices":["Détention < 5% des actions ordinaires","Détention < 10% des actions ordinaires","Détention > 10% des actions ordinaires","Détention > 50% des actions ordinaires"],"answer":2,"source":"Annexe Décision 013/2016 — §14(g) (Participations significatives)","expl":"Une participation est significative au-delà de 10% des actions ordinaires d'une autre entité financière.","exemple":"Détenir 15% d'une autre banque = participation significative, avec un traitement prudentiel spécifique."},
{"cat":"Fonds propres","q":"Quel est le seuil de détention qui distingue les participations non significatives des significatives ?","choices":["5%","10%","20%","33%"],"answer":1,"source":"Annexe Décision 013/2016 — §14(f) et (g)","expl":"Le seuil de 10% de détention distingue les participations non significatives (≤10%) des significatives (>10%).","exemple":"À 9% non significative ; à 11% significative — d'où un traitement différent en fonds propres."},
{"cat":"Fonds propres","q":"Les participations croisées dans le capital d'autres EC/assurance ou entités financières sont :","choices":["Autorisées sans restriction","Visées comme problématiques car elles gonflent artificiellement les fonds propres","Encouragées pour renforcer le système","Soumises uniquement à déclaration"],"answer":1,"source":"Annexe Décision 013/2016 — §14(e) (Participations croisées)","expl":"Les participations croisées entre entités financières sont visées car elles gonflent artificiellement les fonds propres du système.","exemple":"Deux banques se détenant mutuellement afficheraient des fonds propres surévalués ; le dispositif les neutralise."},
{"cat":"Liquidité","q":"Le Ratio de Liquidité à Court Terme (RLCT / LCR) impose aux banques de couvrir leurs sorties nettes de trésorerie sur quel horizon ?","choices":["7 jours","15 jours","30 jours","90 jours"],"answer":2,"source":"Instruction n°009-09-2017 BCEAO — Art. 4 (LCR stress 30 jours)","expl":"Le RLCT/LCR impose de couvrir les sorties nettes de trésorerie sur un horizon de stress de 30 jours.","exemple":"La banque doit détenir assez de HQLA pour tenir 30 jours de retraits en scénario de crise."},
{"cat":"Liquidité","q":"Quel niveau minimum doit atteindre le RLCT à pleine application ?","choices":["75%","100%","110%","125%"],"answer":1,"source":"Instruction n°009-09-2017 BCEAO — Art. 5 (RLCT ≥ 100%)","expl":"À pleine application, le LCR doit être au moins égal à 100% (HQLA ≥ sorties nettes 30 j).","exemple":"Un LCR de 95% signale un déficit de liquidité à court terme à corriger."},
{"cat":"Liquidité","q":"Le Ratio de Liquidité à Long Terme (RLLT / NSFR) compare quels éléments ?","choices":["Actifs liquides / dépôts à vue","Financement stable disponible / financement stable exigé","Crédits à terme / dépôts à terme","Fonds propres / engagements hors bilan"],"answer":1,"source":"Instruction n°009-09-2017 BCEAO — Art. 7 (NSFR : ASF/RSF ≥ 100%)","expl":"Le RLLT/NSFR compare le financement stable disponible (ASF) au financement stable exigé (RSF).","exemple":"Financer des crédits longs par des dépôts stables améliore le NSFR ; les financer à très court terme le dégrade."},
{"cat":"Liquidité","q":"Quel est le ratio minimum exigé pour le NSFR (RLLT) à pleine application ?","choices":["75%","90%","100%","120%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre XIII (NSFR ≥ 100%)","expl":"Le NSFR doit être au moins de 100% à pleine application.","exemple":"Un NSFR < 100% révèle une transformation excessive (actifs longs financés à court terme)."},
{"cat":"Liquidité","q":"Le LCR vise à garantir qu'un établissement dispose d'actifs liquides de haute qualité (HQLA) suffisants pour faire face à :","choices":["Une crise prolongée de 12 mois","Une période de stress de liquidité de 30 jours calendaires","Les retraits quotidiens normaux","Les besoins de financement structurel"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII (LCR, stress 30 jours)","expl":"Le LCR garantit un stock de HQLA suffisant pour absorber un stress de liquidité de 30 jours calendaires.","exemple":"En cas de retraits massifs, les HQLA permettent d'honorer les sorties 30 jours sans recourir à la BCEAO."},
{"cat":"Liquidité","q":"Le NSFR a pour objectif principal :","choices":["Couvrir le risque de marché à court terme","Promouvoir la résilience à moyen et long terme en exigeant un financement plus stable des actifs et activités hors bilan","Réduire les exigences de fonds propres","Augmenter la liquidité immédiate"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII (Objectif NSFR)","expl":"Le NSFR vise la résilience à moyen/long terme en imposant un financement plus stable des actifs et du hors bilan.","exemple":"Il pousse la banque à adosser ses emplois longs à des ressources durables plutôt qu'à un financement volatil."},
{"cat":"Liquidité","q":"Les actifs liquides de haute qualité (HQLA) utilisés dans le calcul du LCR doivent être :","choices":["Uniquement des espèces","Facilement et immédiatement convertibles en espèces, avec peu ou pas de perte de valeur","Des actifs à long terme","Des actifs hypothécaires"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII (Caractéristiques des HQLA)","expl":"Les HQLA doivent être facilement et immédiatement convertibles en cash avec peu ou pas de perte de valeur.","exemple":"Des bons du Trésor UEMOA de qualité comptent en HQLA ; des créances clients illiquides non."},
{"cat":"Liquidité","q":"Le LCR doit-il être respecté à tout moment ?","choices":["Non, uniquement en fin de trimestre","Non, uniquement annuellement","Oui, en permanence, et déclaré mensuellement","Uniquement en cas de crise"],"answer":2,"source":"Instruction n°009-09-2017 BCEAO — Art. 5","expl":"Le LCR doit être respecté en permanence et déclaré mensuellement à la BCEAO.","exemple":"La banque suit son LCR au quotidien et le reporte chaque mois ; le respecter en fin de trimestre ne suffit pas."},
{"cat":"Liquidité","q":"Pour les fonds propres requis dans le numérateur du LCR, on retient :","choices":["Les fonds propres effectifs","Les actifs liquides de haute qualité (HQLA)","Les dépôts de la clientèle","Les encours interbancaires"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII (Numérateur LCR = HQLA)","expl":"Au numérateur du LCR figure le stock d'actifs liquides de haute qualité (HQLA).","exemple":"Plus la banque détient de HQLA, plus son numérateur — et donc son LCR — est élevé."},
{"cat":"Liquidité","q":"Au dénominateur du LCR, on calcule :","choices":["Les fonds propres","Les sorties nettes de trésorerie attendues sur 30 jours en scénario de stress","Le total bilan","Les actifs pondérés"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XIII","expl":"Au dénominateur figurent les sorties nettes de trésorerie attendues sur 30 jours en scénario de stress.","exemple":"On applique des taux de fuite aux dépôts pour estimer les sorties nettes du dénominateur."},
{"cat":"Liquidité","q":"Quelles entités sont assujetties au respect du LCR dans l'UMOA ?","choices":["Uniquement les banques systémiques","Toutes les banques et établissements financiers à caractère bancaire","Uniquement les filiales étrangères","Uniquement les EC dont le total bilan dépasse 100 Mds FCFA"],"answer":1,"source":"Instruction n°009-09-2017 BCEAO","expl":"Toutes les banques et établissements financiers à caractère bancaire de l'UMOA sont assujettis au LCR.","exemple":"Une banque de taille moyenne à Dakar est soumise au LCR au même titre qu'un grand groupe."},
{"cat":"Division risques","q":"Quelle est la limite maximale d'exposition sur un même bénéficiaire (ou groupe de contreparties liées) en % des fonds propres effectifs ?","choices":["10%","20%","25%","40%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre VII Art. 56 (25% des FPE)","expl":"L'exposition maximale sur un même bénéficiaire (ou groupe lié) est plafonnée à 25% des fonds propres effectifs.","exemple":"Avec 40 Mds de FPE, l'engagement total sur un client ne peut dépasser 10 Mds."},
{"cat":"Division risques","q":"À partir de quel seuil une exposition est-elle considérée comme un « grand risque » devant être déclaré à la Commission Bancaire ?","choices":["5% des FPE","10% des FPE","15% des FPE","20% des FPE"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Seuil de déclaration 10%)","expl":"Une exposition ≥ 10% des FPE est un grand risque, à déclarer à la Commission Bancaire.","exemple":"Un engagement de 12% des FPE sur un client doit être reporté comme grand risque."},
{"cat":"Division risques","q":"Quelle est la limite globale cumulée des grands risques en % des fonds propres effectifs ?","choices":["400%","600%","800%","1000%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre VII (Limite globale 8 fois les FPE)","expl":"Le cumul des grands risques ne peut excéder 8 fois (800%) les fonds propres effectifs.","exemple":"La somme de tous les engagements ≥10% des FPE ne doit pas dépasser 8×FPE."},
{"cat":"Division risques","q":"Pour le calcul des grands risques, les expositions à un même bénéficiaire incluent :","choices":["Uniquement les crédits directs","L'ensemble des engagements (crédits, garanties, dérivés, hors bilan) sur le bénéficiaire et les contreparties qui lui sont liées","Uniquement les engagements bilanciels","Uniquement les expositions à plus d'1 an"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Calcul des grands risques)","expl":"On additionne tous les engagements (crédits, garanties, dérivés, hors bilan) sur le bénéficiaire et ses contreparties liées.","exemple":"Crédit + caution + ligne confirmée sur un même groupe s'agrègent pour vérifier la limite de 25%."},
{"cat":"Division risques","q":"Qu'entend-on par « groupe de contreparties liées » dans le dispositif de division des risques ?","choices":["Toutes les contreparties d'un même secteur d'activité","Deux ou plusieurs personnes physiques ou morales qui constituent un risque unique en raison de liens de contrôle ou d'interdépendance économique","Toutes les contreparties d'un même pays","Les contreparties bénéficiant du même taux d'intérêt"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Définition groupe de contreparties liées)","expl":"Un groupe de contreparties liées réunit plusieurs personnes constituant un risque unique par des liens de contrôle ou d'interdépendance économique.","exemple":"Une société mère et sa filiale sont traitées comme un seul bénéficiaire pour la limite de 25%."},
{"cat":"Division risques","q":"Les expositions sur les États souverains de l'UEMOA en monnaie locale sont-elles soumises aux limites de la division des risques ?","choices":["Oui, plafonnées à 25%","Non, elles bénéficient d'une exemption en raison de leur pondération nulle","Oui, plafonnées à 50%","Oui, plafonnées à 100%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Exemptions)","expl":"Les expositions sur les États UEMOA en monnaie locale sont exemptées des limites de division des risques (pondération nulle).","exemple":"Détenir des bons du Trésor sénégalais en FCFA n'entre pas dans la limite de 25% par bénéficiaire."},
{"cat":"Division risques","q":"Les expositions sur la BCEAO sont :","choices":["Soumises à la limite de 25%","Exemptées des limites de division des risques","Soumises à une limite spéciale de 100%","Pondérées à 100%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VII (Exemptions BCEAO)","expl":"Les expositions sur la BCEAO sont exemptées des limites de division des risques.","exemple":"Les avoirs déposés à la BCEAO ne sont pas plafonnés par la limite de 25%."},
{"cat":"Gouvernance","q":"Quel organe est obligatoire au sein du conseil d'administration de tout établissement de crédit selon le dispositif UMOA ?","choices":["Comité de rémunération uniquement","Comité d'audit","Comité stratégie commerciale","Aucun comité n'est obligatoire"],"answer":1,"source":"Circulaire n°01-2017 CB-UMOA — Art. 24 (Comité d'audit obligatoire)","expl":"Tout établissement de crédit doit se doter d'un comité d'audit au sein de son conseil d'administration.","exemple":"Le conseil constitue un comité d'audit chargé de superviser le contrôle interne et l'information financière."},
{"cat":"Gouvernance","q":"Combien d'administrateurs indépendants sont exigés au minimum dans le conseil d'administration ?","choices":["Aucun","Au moins 1","Au moins 2","Au moins le tiers"],"answer":2,"source":"Circulaire n°01-2017 CB-UMOA — Art. 18 (Min. 2 administrateurs indépendants)","expl":"Le conseil d'administration doit compter au moins 2 administrateurs indépendants.","exemple":"La banque nomme au minimum deux administrateurs sans lien d'intérêt avec la direction."},
{"cat":"Gouvernance","q":"La fonction de contrôle interne doit obligatoirement être indépendante de quelles autres fonctions ?","choices":["Audit interne uniquement","Conformité uniquement","Audit interne et gestion des risques","Direction générale uniquement"],"answer":2,"source":"Circulaire n°04-2017 CB-UMOA — Art. 8 (3 lignes de défense)","expl":"La fonction de contrôle interne doit être indépendante de l'audit interne et de la gestion des risques.","exemple":"Le responsable conformité ne peut cumuler avec l'audit interne ni le pilotage des risques."},
{"cat":"Gouvernance","q":"Combien de lignes de défense compose le dispositif de contrôle interne d'un établissement de crédit UMOA ?","choices":["1 ligne","2 lignes","3 lignes","4 lignes"],"answer":2,"source":"Circulaire n°04-2017 CB-UMOA (3 lignes : opérationnel / risques+conformité / audit interne)","expl":"Le contrôle interne repose sur 3 lignes de défense : opérationnel / risques+conformité / audit interne.","exemple":"L'agence (1re ligne) prend le risque, la conformité (2e) le surveille, l'audit interne (3e) évalue le dispositif."},
{"cat":"Gouvernance","q":"Que se passe-t-il en cas de non-respect des normes prudentielles par un établissement de crédit ?","choices":["Aucune conséquence si régularisation sous 30 jours","La Commission Bancaire adresse une injonction + interdiction de distributions discrétionnaires (dividendes, rachats d'actions, primes) durant la période de non-conformité","Sanction pénale immédiate","Retrait automatique d'agrément"],"answer":1,"source":"Annexe Décision 013/2016 — §3 (Injonction + interdiction distributions)","expl":"En cas de non-respect, la Commission Bancaire adresse une injonction et interdit les distributions discrétionnaires (dividendes, rachats, primes) pendant la non-conformité.","exemple":"Une banque sous ses ratios ne peut plus verser de dividendes tant qu'elle n'est pas revenue en conformité."},
{"cat":"Gouvernance","q":"L'agrément des dirigeants d'un établissement de crédit relève de :","choices":["L'Assemblée Générale uniquement","La Commission Bancaire de l'UMOA","Le Ministre des Finances","Le Conseil d'Administration uniquement"],"answer":1,"source":"Loi uniforme portant réglementation bancaire","expl":"L'agrément des dirigeants d'un établissement de crédit relève de la Commission Bancaire de l'UMOA.","exemple":"La nomination d'un nouveau DG est soumise à l'agrément de la Commission Bancaire."},
{"cat":"Gouvernance","q":"Les exigences en matière de gouvernance s'appliquent-elles aux compagnies financières ?","choices":["Non, uniquement aux banques","Oui, sur base individuelle et consolidée","Uniquement aux filiales","Uniquement aux maisons-mères"],"answer":1,"source":"Décision 014/2016 CM/UMOA — Art. 7 (Application aux compagnies financières)","expl":"Les exigences de gouvernance s'appliquent aux compagnies financières sur base individuelle et consolidée.","exemple":"Une holding financière applique les règles de gouvernance à son niveau et à celui du groupe."},
{"cat":"Piliers Bâle","q":"Le Pilier 1 du dispositif prudentiel UMOA couvre principalement :","choices":["La gouvernance et la transparence","Les exigences minimales de fonds propres (risque de crédit, de marché, opérationnel)","Le processus de surveillance prudentielle","La discipline de marché"],"answer":1,"source":"Annexe Décision 013/2016 — Architecture Bâle II/III (Pilier 1)","expl":"Le Pilier 1 couvre les exigences minimales de fonds propres pour les risques de crédit, de marché et opérationnel.","exemple":"Le calcul des APR et du capital requis pour ces trois risques relève du Pilier 1."},
{"cat":"Piliers Bâle","q":"Le Pilier 2 (processus de surveillance prudentielle) inclut notamment :","choices":["Le calcul du ratio Cooke","L'ICAAP (évaluation interne de l'adéquation des fonds propres) et le SREP","La publication semestrielle des comptes","Le ratio de levier uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XI (Pilier 2, ICAAP/SREP)","expl":"Le Pilier 2 (surveillance prudentielle) inclut l'ICAAP (auto-évaluation de l'adéquation des fonds propres) et le SREP.","exemple":"La banque évalue en interne (ICAAP) si ses fonds propres couvrent tous ses risques ; la CB revoit (SREP)."},
{"cat":"Piliers Bâle","q":"Le Pilier 3 (discipline de marché) impose la publication :","choices":["Du seul bilan annuel","D'informations sur la structure des fonds propres, l'exposition aux risques et la gestion des risques","Des seuls ratios prudentiels","Du rapport d'audit externe uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XII (Pilier 3)","expl":"Le Pilier 3 (discipline de marché) impose la publication d'informations sur les fonds propres, l'exposition aux risques et leur gestion.","exemple":"La banque publie un rapport Pilier 3 permettant au marché d'apprécier son profil de risque."},
{"cat":"Piliers Bâle","q":"Quelle est la périodicité minimale obligatoire de publication des informations du Pilier 3 ?","choices":["Mensuelle","Trimestrielle","Semestrielle","Annuelle"],"answer":2,"source":"Annexe Décision 013/2016 — Titre XII (Périodicité semestrielle)","expl":"La publication des informations du Pilier 3 est au minimum semestrielle.","exemple":"La banque diffuse ses informations Pilier 3 deux fois par an."},
{"cat":"Piliers Bâle","q":"L'ICAAP (Processus Interne d'Évaluation de l'Adéquation des Fonds Propres) a pour objectif de :","choices":["Calculer le ratio Cooke","Permettre à l'établissement d'évaluer en interne l'adéquation de ses fonds propres face à l'ensemble de ses risques","Réduire les exigences de fonds propres","Externaliser l'évaluation des risques"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XI (ICAAP)","expl":"L'ICAAP permet à la banque d'évaluer en interne l'adéquation de ses fonds propres face à l'ensemble de ses risques.","exemple":"Au-delà du Pilier 1, l'ICAAP couvre aussi le risque de taux du portefeuille bancaire."},
{"cat":"Piliers Bâle","q":"Le SREP (Supervisory Review and Evaluation Process) est conduit par :","choices":["L'établissement de crédit lui-même","La Commission Bancaire de l'UMOA","Les commissaires aux comptes","Le Conseil d'Administration"],"answer":1,"source":"Annexe Décision 013/2016 — Titre XI (Processus SREP par CB-UMOA)","expl":"Le SREP est conduit par la Commission Bancaire de l'UMOA.","exemple":"La CB revoit l'ICAAP de la banque et peut exiger un supplément de fonds propres au titre du Pilier 2."},
{"cat":"Piliers Bâle","q":"Le dispositif UMOA s'inspire de quelle architecture internationale ?","choices":["Bâle I uniquement","Bâle II et Bâle III","Solvabilité II","MiFID II"],"answer":1,"source":"Annexe Décision 013/2016 — Préambule (Architecture Bâle II/III adaptée à l'UMOA)","expl":"Le dispositif UMOA s'inspire de l'architecture Bâle II et Bâle III, adaptée à la zone.","exemple":"Ratios de solvabilité, coussins, LCR/NSFR reprennent la logique bâloise transposée à l'UMOA."},
{"cat":"Piliers Bâle","q":"Pour le Pilier 1, l'approche UMOA est :","choices":["Modèles internes avancés obligatoires","Approche STANDARD (pas de modèles internes)","Au choix de l'établissement","Approche par modèle propriétaire"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Approche standard)","expl":"Pour le Pilier 1, l'UMOA retient l'approche standard, sans modèles internes.","exemple":"Les pondérations de risque sont fixées par le régulateur ; la banque ne calcule pas ses propres coefficients."},
{"cat":"Ratio levier","q":"Quel est le niveau minimum du ratio de levier (Tier 1 / Exposition totale) imposé aux établissements de l'UMOA ?","choices":["1%","2%","3%","5%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre VIII (Ratio de levier ≥ 3%)","expl":"Le ratio de levier (Tier 1 / exposition totale) doit être au moins de 3%.","exemple":"Une banque à fort hors bilan doit garder Tier 1 ≥ 3% de son exposition totale non pondérée."},
{"cat":"Ratio levier","q":"Le dispositif prudentiel UMOA est entré en vigueur à quelle date, avec quelle période de transition ?","choices":["1er janvier 2017 — transition 3 ans","1er janvier 2018 — transition jusqu'en 2022","1er juillet 2018 — transition 2 ans","1er janvier 2020 — transition 5 ans"],"answer":1,"source":"Décision 013/2016 CM/UMOA — Art. 3 (Entrée en vigueur 01/01/2018)","expl":"Le dispositif prudentiel UMOA est entré en vigueur le 1er janvier 2018, avec une transition jusqu'en 2022.","exemple":"Les exigences ont été relevées par paliers de 2018 à leur cible pleine en 2022."},
{"cat":"Ratio levier","q":"Au numérateur du ratio de levier, on retient :","choices":["Les fonds propres effectifs (FPE)","Les fonds propres de catégorie 1 (Tier 1 = CET1 + AT1)","Le CET1 uniquement","Le T2 uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VIII (Numérateur = T1)","expl":"Au numérateur du ratio de levier figure le Tier 1 (CET1 + AT1).","exemple":"Seuls les fonds propres de catégorie 1 comptent au numérateur, pas le T2."},
{"cat":"Ratio levier","q":"Au dénominateur du ratio de levier, on calcule :","choices":["Les actifs pondérés des risques","Une mesure non pondérée de l'exposition totale (bilan + hors bilan)","Les seuls actifs liquides","Les fonds propres complémentaires"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VIII","expl":"Au dénominateur du levier figure une mesure non pondérée de l'exposition totale (bilan + hors bilan).","exemple":"Contrairement au ratio de solvabilité, aucune pondération de risque n'est appliquée au dénominateur du levier."},
{"cat":"Ratio levier","q":"Le ratio de levier vise principalement à :","choices":["Augmenter les fonds propres pondérés","Limiter l'effet de levier excessif et compléter le ratio fondé sur les risques (filet de sécurité non risqué)","Remplacer les autres ratios","Réduire le coût du capital"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VIII (Objectif backstop)","expl":"Le ratio de levier limite l'effet de levier excessif et sert de filet de sécurité non risqué complétant le ratio de solvabilité.","exemple":"Même avec des actifs faiblement pondérés, la banque reste bornée par le levier de 3%."},
{"cat":"Ratio levier","q":"La période de transition du dispositif prudentiel UMOA s'étend de :","choices":["2018 à 2020","2018 à 2022","2017 à 2022","2019 à 2025"],"answer":1,"source":"Décision 013/2016 CM/UMOA — Art. 3 (Application pleine 2022)","expl":"La période de transition s'étend de 2018 à 2022, année d'application pleine.","exemple":"Les coussins ont été introduits progressivement jusqu'à leur niveau cible en 2022."},
{"cat":"Ratio levier","q":"Pour le coussin de conservation, la transition se fait par paliers de :","choices":["0,5% par an","0,625% par an de 2019 à 2022","1% par an","2,5% en une seule fois"],"answer":1,"source":"Annexe Décision 013/2016 — Titre III (Transition coussin)","expl":"Le coussin de conservation a été introduit par paliers de 0,625% par an de 2019 à 2022.","exemple":"0,625% en 2019, 1,25% en 2020… jusqu'à 2,5% en 2022."},
{"cat":"Ratio levier","q":"Que se passe-t-il si un établissement ne respecte pas le coussin de conservation ?","choices":["Rien de particulier","Restrictions sur les distributions discrétionnaires (dividendes, rachats d'actions, primes variables) proportionnelles au non-respect","Sanction pénale immédiate","Retrait d'agrément"],"answer":1,"source":"Annexe Décision 013/2016 — Titre III (Restrictions distributions)","expl":"Ne pas respecter le coussin de conservation entraîne des restrictions de distributions discrétionnaires, proportionnelles au manquement.","exemple":"Plus la banque entame le coussin, plus la part de bénéfices distribuable (dividendes, primes) est réduite."},
{"cat":"APR","q":"Quelle est la pondération en risque d'une créance sur un État souverain de l'UEMOA libellée et financée en FCFA ?","choices":["0%","20%","50%","100%"],"answer":0,"source":"Annexe Décision 013/2016 — Titre IV Art. 46 (Pondération 0%)","expl":"Une créance sur un État UEMOA libellée et financée en FCFA est pondérée à 0%.","exemple":"Des bons du Trésor sénégalais en FCFA n'exigent aucun fonds propres au titre du risque de crédit."},
{"cat":"APR","q":"Quelle pondération s'applique à une créance sur la BCEAO ?","choices":["0%","20%","50%","100%"],"answer":0,"source":"Annexe Décision 013/2016 — Titre IV (Pondération 0% BCEAO)","expl":"Une créance sur la BCEAO est pondérée à 0%.","exemple":"Les réserves déposées à la BCEAO ne consomment pas de fonds propres."},
{"cat":"APR","q":"Quelle pondération s'applique à une exposition sur une banque de notation entre A+ et A- ?","choices":["20%","50%","75%","100%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Pondération expositions bancaires)","expl":"Une exposition sur une banque notée entre A+ et A- est pondérée à 50%.","exemple":"Un placement interbancaire sur une contrepartie notée A pèse 50% de son montant en APR."},
{"cat":"APR","q":"Pour les expositions sur les entreprises non notées, quelle pondération s'applique par défaut ?","choices":["75%","100%","150%","200%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Pondération entreprises non notées 100%)","expl":"Par défaut, une exposition sur une entreprise non notée est pondérée à 100%.","exemple":"Un crédit à une PME sans notation externe compte pour 100% de son encours en APR."},
{"cat":"APR","q":"Quelle pondération s'applique au portefeuille de crédits sur la clientèle de détail (retail) ?","choices":["50%","75%","100%","150%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Pondération retail 75%)","expl":"Le portefeuille de crédits de détail (retail) est pondéré à 75%.","exemple":"Un portefeuille de crédits à la consommation diversifié pèse 75% de son encours en APR."},
{"cat":"APR","q":"Pour les expositions de financement immobilier résidentiel intégralement garanties par une hypothèque, quelle pondération s'applique ?","choices":["20%","35%","75%","100%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (Pondération hypothécaire résidentiel 35%)","expl":"Un financement immobilier résidentiel intégralement garanti par hypothèque est pondéré à 35%.","exemple":"Un prêt logement bien garanti par hypothèque consomme moins de fonds propres (35%) qu'un crédit non garanti."},
{"cat":"APR","q":"Les créances en souffrance (impayées de plus de 90 jours, non provisionnées ou avec provision < 20%) sont pondérées à :","choices":["75%","100%","150%","200%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre IV (Pondération créances en souffrance 150%)","expl":"Les créances impayées de plus de 90 jours, non provisionnées ou provisionnées < 20%, sont pondérées à 150%.","exemple":"Un impayé ancien peu provisionné alourdit les APR (150%) et pèse sur la solvabilité."},
{"cat":"APR","q":"Les expositions sur les Banques Multilatérales de Développement (BMD) qualifiées (BIRD, BAD, etc.) sont pondérées à :","choices":["0%","20%","50%","100%"],"answer":0,"source":"Annexe Décision 013/2016 — Titre IV (BMD qualifiées : 0%)","expl":"Les expositions sur les banques multilatérales de développement qualifiées (BIRD, BAD…) sont pondérées à 0%.","exemple":"Un placement garanti par la BAD n'exige pas de fonds propres au titre du risque de crédit."},
{"cat":"APR","q":"L'approche standard pour le risque de crédit dans l'UMOA s'appuie sur :","choices":["Des modèles internes des banques","Les notations externes (OEEC : Organismes Externes d'Évaluation du Crédit) reconnus par la Commission Bancaire","Les notations de la BCEAO uniquement","Aucune notation externe"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV Chapitre 1 (Approche standard)","expl":"L'approche standard du risque de crédit s'appuie sur les notations d'OEEC reconnus par la Commission Bancaire.","exemple":"La pondération d'une contrepartie dépend de la note attribuée par une agence reconnue."},
{"cat":"APR","q":"Que désigne l'« Atténuation du Risque de Crédit » (ARC) dans le dispositif prudentiel ?","choices":["L'annulation pure et simple du risque","L'ensemble des techniques (sûretés, garanties, dérivés de crédit) permettant de réduire l'exigence en fonds propres au titre du risque de crédit","Le rééchelonnement automatique des créances","Le partage du risque avec la BCEAO"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV Chapitre 3 (ARC)","expl":"L'atténuation du risque de crédit (ARC) regroupe les techniques (sûretés, garanties, dérivés) réduisant l'exigence en fonds propres.","exemple":"Une garantie en cash reçue réduit l'exposition pondérée d'un crédit."},
{"cat":"APR","q":"Quelle pondération s'applique à une exposition sur les PME éligibles au régime « retail » ?","choices":["50%","75%","100%","125%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (PME retail : 75%)","expl":"Une exposition sur une PME éligible au régime retail est pondérée à 75%.","exemple":"Un petit crédit à une PME diversifiée bénéficie de la pondération retail de 75%."},
{"cat":"APR","q":"Le « Facteur de Conversion en Équivalent Crédit » (FCEC) s'applique aux :","choices":["Expositions bilancielles uniquement","Engagements de hors bilan, pour les convertir en équivalent risque de crédit","Expositions sur les souverains","Dépôts à terme uniquement"],"answer":1,"source":"Annexe Décision 013/2016 — Titre IV (FCEC pour hors bilan)","expl":"Le FCEC convertit les engagements de hors bilan en équivalent risque de crédit.","exemple":"Une ligne de crédit non tirée est convertie via le FCEC avant d'être pondérée."},
{"cat":"APR","q":"Pour les engagements de crédit confirmés annulables sans condition, le FCEC est de :","choices":["0%","20%","50%","100%"],"answer":0,"source":"Annexe Décision 013/2016 — Titre IV (FCEC engagements annulables 0%)","expl":"Un engagement confirmé annulable sans condition a un FCEC de 0%.","exemple":"Une autorisation de découvert révocable à tout moment n'entre pas dans les APR (FCEC 0%)."},
{"cat":"APR","q":"Pour les engagements de crédit confirmés d'une durée supérieure à 1 an, le FCEC est de :","choices":["0%","20%","50%","100%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre IV (FCEC engagements > 1 an : 50%)","expl":"Un engagement de crédit confirmé de durée supérieure à 1 an a un FCEC de 50%.","exemple":"Une ligne confirmée à 18 mois est prise pour 50% de son montant avant pondération."},
{"cat":"APR","q":"Quel est l'objectif principal du calcul des Actifs Pondérés des Risques (APR) ?","choices":["Déterminer le coût du capital","Mesurer l'exposition aux risques pour calculer les exigences minimales de fonds propres","Déterminer le résultat fiscal","Calculer la valeur ajoutée"],"answer":1,"source":"Annexe Décision 013/2016 — Titre III (Objectif APR)","expl":"Le calcul des APR mesure l'exposition aux risques pour déterminer les exigences minimales en fonds propres.","exemple":"Plus les actifs sont risqués, plus les APR — et donc le capital requis — sont élevés."},
{"cat":"Risque opérationnel","q":"Que désigne le « risque opérationnel » dans le dispositif prudentiel UMOA ?","choices":["Uniquement les pertes liées à la fraude interne","Le risque de pertes résultant d'une inadéquation ou défaillance des processus internes, du personnel, des systèmes, ou d'événements externes","Le risque de marché","Le risque de crédit"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Définition risque opérationnel)","expl":"Le risque opérationnel est le risque de pertes dues à une défaillance des processus, du personnel, des systèmes, ou à des événements externes.","exemple":"Une fraude interne ou une panne informatique génératrice de pertes relève du risque opérationnel."},
{"cat":"Risque opérationnel","q":"Le risque opérationnel inclut-il le risque juridique ?","choices":["Non","Oui, le risque juridique est inclus dans le risque opérationnel","Uniquement pour les contentieux > 1 M FCFA","Uniquement les litiges avec la BCEAO"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V","expl":"Le risque juridique est inclus dans le risque opérationnel.","exemple":"Une condamnation pour vice de procédure sur un contrat est une perte de risque opérationnel."},
{"cat":"Risque opérationnel","q":"Le risque opérationnel exclut explicitement :","choices":["Le risque de fraude","Les risques stratégiques et de réputation","Le risque de défaillance des systèmes informatiques","Le risque d'erreur humaine"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Exclusions : stratégique et réputation)","expl":"Le risque opérationnel exclut explicitement les risques stratégique et de réputation.","exemple":"Une mauvaise décision stratégique n'entre pas dans le calcul du capital pour risque opérationnel."},
{"cat":"Risque opérationnel","q":"Quelle approche de calcul des exigences en fonds propres au titre du risque opérationnel est applicable dans l'UMOA ?","choices":["Approche AMA (Advanced Measurement Approach) uniquement","Approche standard fondée sur le Produit Net Bancaire (PNB) annuel sur 3 ans","Approche modèle interne uniquement","Aucune exigence spécifique"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Approche standard PNB)","expl":"L'exigence pour risque opérationnel est calculée selon l'approche standard fondée sur le PNB annuel sur 3 ans.","exemple":"Pas de modèle interne : on part du PNB des 3 derniers exercices."},
{"cat":"Risque opérationnel","q":"Le calcul des exigences en fonds propres au titre du risque opérationnel se base sur :","choices":["Le total bilan","Le PNB (Produit Net Bancaire) moyen des 3 derniers exercices, affecté d'un coefficient","Le résultat net","Les fonds propres"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Méthode de calcul)","expl":"Le calcul se base sur le PNB moyen des 3 derniers exercices, affecté d'un coefficient.","exemple":"On moyenne le PNB de 3 ans puis on applique le coefficient réglementaire."},
{"cat":"Risque opérationnel","q":"Si pour une année donnée le PNB est négatif ou nul, comment est-il pris en compte dans le calcul ?","choices":["Il est compté tel quel (négatif)","Il est exclu du calcul et le coefficient s'applique aux 2 années restantes","Il est forcé à zéro","Il est doublé"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (PNB négatif/nul : exclusion)","expl":"Une année à PNB négatif ou nul est exclue et le coefficient s'applique aux 2 années restantes.","exemple":"Si l'année N-1 a un PNB négatif, la moyenne se fait sur N et N-2 seulement."},
{"cat":"Risque opérationnel","q":"Le coefficient appliqué au PNB pour le calcul de l'exigence en fonds propres au titre du risque opérationnel est de :","choices":["8%","12%","15%","20%"],"answer":2,"source":"Annexe Décision 013/2016 — Titre V (Coefficient 15%)","expl":"Le coefficient appliqué au PNB pour l'exigence de risque opérationnel est de 15%.","exemple":"Pour un PNB moyen de 20 Mds, l'exigence de base est de 3 Mds (15%)."},
{"cat":"Risque opérationnel","q":"La gestion du risque opérationnel doit inclure un dispositif de :","choices":["Modèle économique unique","Collecte des pertes opérationnelles, identification des indicateurs clés de risque (KRI), et plan de continuité d'activité (PCA)","Suppression de tous les processus manuels","Externalisation totale"],"answer":1,"source":"Annexe Décision 013/2016 — Titre V (Cadre de gestion)","expl":"La gestion du risque opérationnel doit inclure la collecte des pertes, des indicateurs clés de risque (KRI) et un plan de continuité d'activité (PCA).","exemple":"La banque tient une base des incidents et un PCA pour rester opérationnelle en cas de sinistre."},
{"cat":"Risque de marché","q":"Que regroupe le risque de marché dans le dispositif prudentiel ?","choices":["Uniquement le risque de change","Le risque de taux d'intérêt sur le portefeuille de négociation, le risque sur titres de propriété, le risque de change et le risque sur produits de base","Uniquement le risque de crédit","Le risque opérationnel"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI (Composantes du risque de marché)","expl":"Le risque de marché regroupe le risque de taux du portefeuille de négociation, le risque actions, le risque de change et le risque sur produits de base.","exemple":"Une position de trading sur devises ou obligations expose la banque au risque de marché."},
{"cat":"Risque de marché","q":"Le portefeuille de négociation se distingue du portefeuille bancaire par :","choices":["Sa taille uniquement","L'intention de négociation à court terme pour profiter des mouvements de prix, vs détention durable","La devise utilisée","Le secteur d'activité"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI Chapitre 1","expl":"Le portefeuille de négociation se distingue du portefeuille bancaire par l'intention de négociation à court terme pour profiter des mouvements de prix.","exemple":"Un titre acheté pour être revendu vite est en trading ; un titre détenu durablement est en portefeuille bancaire."},
{"cat":"Risque de marché","q":"L'exigence en fonds propres au titre du risque de change s'applique :","choices":["Uniquement au portefeuille de négociation","À la position nette globale en devises de l'établissement (bilan + hors bilan)","Uniquement aux actifs libellés en EUR","Uniquement si la position dépasse 50% du capital"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI (Risque de change)","expl":"L'exigence pour risque de change porte sur la position nette globale en devises (bilan + hors bilan).","exemple":"On additionne les positions en euros, dollars… pour mesurer l'exposition de change à couvrir."},
{"cat":"Risque de marché","q":"Pour le risque de marché, l'UMOA applique :","choices":["L'approche par modèles internes","L'approche standard (méthode de mesure standardisée)","Au choix de l'établissement","Aucune exigence"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI Chapitre 2 (Approche standard)","expl":"Pour le risque de marché, l'UMOA applique l'approche standard (mesure standardisée).","exemple":"Les coefficients de risque de marché sont fixés par le régulateur, pas par modèle interne."},
{"cat":"Risque de marché","q":"Le risque de taux d'intérêt dans le portefeuille bancaire (IRRBB) est-il traité au titre du Pilier 1 ?","choices":["Oui, exigence minimale standard","Non, il relève du Pilier 2 (processus de surveillance prudentielle)","Oui pour certaines banques uniquement","Il n'est pas couvert"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI / Pilier 2","expl":"Le risque de taux du portefeuille bancaire (IRRBB) relève du Pilier 2, pas du Pilier 1.","exemple":"La sensibilité des marges d'intérêt aux taux est évaluée dans l'ICAAP (Pilier 2)."},
{"cat":"Risque de marché","q":"Pour les positions en titres de propriété (actions), le risque général de marché applique un coefficient de :","choices":["4%","8%","12%","16%"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI Chapitre 2 (Actions : 8%)","expl":"Pour les positions en actions, le risque général de marché applique un coefficient de 8%.","exemple":"Un portefeuille actions de trading exige 8% de son montant en fonds propres au titre du risque général."},
{"cat":"Risque de marché","q":"Pour les positions en produits de base (commodités), un coefficient additionnel s'applique au :","choices":["Notionnel","Risque spécifique et risque général","Bilan total","PNB"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI","expl":"Pour les produits de base, un coefficient additionnel s'applique au risque spécifique et au risque général.","exemple":"Une position sur matières premières combine exigence spécifique et générale."},
{"cat":"Risque de marché","q":"Une « petite » position nette en devises peut bénéficier d'une exemption d'exigence en fonds propres si elle est inférieure à :","choices":["1% du Tier 1","2% des FPE","5% du capital","10% du bilan"],"answer":1,"source":"Annexe Décision 013/2016 — Titre VI (Seuil minimum risque de change)","expl":"Une position nette en devises peut être exemptée d'exigence si elle est inférieure à 2% des FPE.","exemple":"Une exposition de change résiduelle sous 2% des FPE ne génère pas d'exigence."},
{"cat":"Supervision consolidée","q":"Qui institue le dispositif de supervision sur base consolidée des EC et compagnies financières dans l'UMOA ?","choices":["L'Avis BCEAO 004-04-2016","La Décision N°014/24/06/2016/CM/UMOA du 24 juin 2016","La Loi uniforme bancaire","Le Traité UMOA"],"answer":1,"source":"Décision N°014/24/06/2016/CM/UMOA — Préambule","expl":"La supervision sur base consolidée est instituée par la Décision N°014/24/06/2016/CM/UMOA.","exemple":"C'est ce texte qui fonde le contrôle des groupes bancaires au niveau consolidé."},
{"cat":"Supervision consolidée","q":"Quel est le seuil de % du bilan groupe permettant de qualifier un groupe comme ayant des « activités à dominante bancaire » ?","choices":["20%","30%","40%","50%"],"answer":2,"source":"Décision 014/2016 — Art. 1(a) (Seuil 40%)","expl":"Un groupe est à dominante bancaire lorsque l'activité bancaire dépasse 40% du bilan groupe.","exemple":"Un conglomérat dont plus de 40% du bilan est bancaire entre dans le champ de la supervision consolidée."},
{"cat":"Supervision consolidée","q":"Que désigne une « compagnie financière holding intermédiaire » ?","choices":["Toute société holding industrielle","Une entité non agréée comme EC, qui détient l'ensemble des participations d'un groupe dans ses filiales EC opérant dans l'UMOA","Une succursale étrangère","Une filiale d'assurance"],"answer":1,"source":"Décision 014/2016 — Art. 1(c)(ii)","expl":"La compagnie financière holding intermédiaire est une entité non agréée EC détenant l'ensemble des participations du groupe dans ses filiales EC opérant dans l'UMOA.","exemple":"Une holding regroupant les filiales bancaires d'un groupe étranger dans l'UMOA."},
{"cat":"Supervision consolidée","q":"Que désigne le « contrôle exclusif de droit » ?","choices":["La détention de 25% des droits de vote","La détention directe ou indirecte de plus de la moitié des droits de vote d'une filiale","Un contrôle assuré par convention","Une influence sans détention"],"answer":1,"source":"Décision 014/2016 — Art. 1(e)(i)","expl":"Le contrôle exclusif de droit correspond à la détention, directe ou indirecte, de plus de la moitié des droits de vote.","exemple":"Détenir 60% des droits de vote d'une filiale confère un contrôle exclusif de droit."},
{"cat":"Supervision consolidée","q":"L'« influence notable » d'une entreprise sur une autre est présumée à partir de quel seuil de droits de vote ?","choices":["10%","20%","30%","50%"],"answer":1,"source":"Décision 014/2016 — Art. 1(m) (Présomption : >20%)","expl":"L'influence notable est présumée à partir de 20% des droits de vote.","exemple":"Une participation de 25% fait présumer une influence notable sur l'entité."},
{"cat":"Supervision consolidée","q":"Sont exclues du périmètre de consolidation prudentielle :","choices":["Toutes les entreprises à caractère financier","Les sociétés à objet commercial, entreprises non financières, et entreprises à caractère financier dont le bilan est < 1% du total consolidé","Uniquement les filiales étrangères","Aucune entité"],"answer":1,"source":"Décision 014/2016 — Art. 4 (Exclusions)","expl":"Sont exclues les sociétés commerciales, entreprises non financières et entités financières dont le bilan est inférieur à 1% du total consolidé.","exemple":"Une petite filiale financière pesant 0,5% du groupe peut être exclue du périmètre consolidé."},
{"cat":"Supervision consolidée","q":"Les entités du secteur des assurances sont-elles incluses dans le périmètre de consolidation prudentielle bancaire ?","choices":["Oui, sans distinction","Non, elles sont explicitement exclues","Uniquement si le bilan dépasse 10%","Uniquement pour les filiales contrôlées"],"answer":1,"source":"Décision 014/2016 — Art. 4 (Exclusion assurances)","expl":"Les entités d'assurance sont explicitement exclues du périmètre de consolidation prudentielle bancaire.","exemple":"La filiale d'assurance d'un groupe bancaire n'entre pas dans la consolidation prudentielle bancaire."},
{"cat":"Supervision consolidée","q":"La Commission Bancaire peut requérir d'une maison-mère qu'elle crée dans l'UMOA :","choices":["Une filiale d'assurance","Une compagnie financière holding intermédiaire détenant les participations du groupe dans ses EC","Une fondation","Un comité scientifique"],"answer":1,"source":"Décision 014/2016 — Art. 5","expl":"La CB peut requérir d'une maison-mère la création d'une compagnie financière holding intermédiaire détenant les participations du groupe dans ses EC.","exemple":"Pour rendre le groupe supervisable, la CB impose une holding intermédiaire coiffant les filiales bancaires."},
{"cat":"Supervision consolidée","q":"La supervision sur base consolidée s'applique aux :","choices":["EC maisons-mères détenant au moins une filiale EC dans l'UMOA, et compagnies financières holding ou holding intermédiaires implantées dans l'UMOA","Toutes les banques sans condition","Uniquement les groupes de plus de 5 banques","Uniquement les groupes étrangers"],"answer":0,"source":"Décision 014/2016 — Art. 3 (Champ d'application)","expl":"La supervision consolidée s'applique aux EC maisons-mères détenant au moins une filiale EC dans l'UMOA et aux compagnies financières holding/intermédiaires implantées dans l'UMOA.","exemple":"Un groupe avec une banque mère et des filiales bancaires est supervisé sur base consolidée."},
{"cat":"Supervision consolidée","q":"La Commission Bancaire de l'UMOA tient et publie quelle liste annuelle ?","choices":["La liste des banques en faillite","La liste des compagnies financières qu'elle supervise sur base consolidée","La liste des actionnaires bancaires","La liste des prêts en souffrance"],"answer":1,"source":"Décision 014/2016 — Art. 6 (Liste annuelle)","expl":"La CB tient et publie la liste des compagnies financières qu'elle supervise sur base consolidée.","exemple":"Un groupe figurant sur cette liste sait qu'il est soumis au contrôle consolidé."},
{"cat":"Supervision consolidée","q":"Quel est le pouvoir de la Commission Bancaire face à des structures de capital empêchant la supervision consolidée ?","choices":["Aucun pouvoir","Elle peut ne pas autoriser des structures de capital ou d'organisation qui font obstacle à la consolidation des données","Uniquement émettre des recommandations","Uniquement avec l'accord du Ministre"],"answer":1,"source":"Décision 014/2016 — Art. 9 (Pouvoirs)","expl":"La CB peut refuser des structures de capital ou d'organisation faisant obstacle à la consolidation des données.","exemple":"Un montage opaque empêchant la consolidation peut être refusé par la CB."},
{"cat":"FODEP","q":"Que désigne le sigle FODEP dans la réglementation bancaire UMOA ?","choices":["Fonds de Développement Productif","Formulaire de Déclaration Prudentielle","Fonds d'Opérations Bancaires","Force Opérationnelle de Défense Prudentielle"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 3 (Définition FODEP)","expl":"FODEP = Formulaire de Déclaration Prudentielle, support de reporting des ratios à la BCEAO.","exemple":"La banque renseigne le FODEP pour déclarer sa solvabilité, sa liquidité, etc."},
{"cat":"FODEP","q":"Quelle est la périodicité de transmission du FODEP à la BCEAO par les établissements assujettis ?","choices":["Mensuelle","Trimestrielle","Semestrielle","Annuelle"],"answer":2,"source":"Instruction n°005-08-2017 BCEAO — Art. 4 (Semestrielle)","expl":"Le FODEP est transmis à la BCEAO selon une périodicité semestrielle.","exemple":"Deux envois par an du FODEP à la BCEAO."},
{"cat":"FODEP","q":"Quelles sont les dates limites de transmission du FODEP à la BCEAO ?","choices":["31 mars et 30 septembre","30 avril et 31 octobre","31 mai et 30 novembre","30 juin et 31 décembre"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 4 (30 avril et 31 octobre)","expl":"Les dates limites de transmission du FODEP sont le 30 avril et le 31 octobre.","exemple":"Le reporting arrêté au 31/12 est dû au 30 avril ; celui arrêté au 30/06, au 31 octobre."},
{"cat":"FODEP","q":"Sur quelle base est arrêté le FODEP transmis au 30 avril ?","choices":["Les comptes du 1er trimestre","Les comptes annuels arrêtés au 31 décembre de l'année précédente","Les comptes au 30 juin","Les comptes prévisionnels"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 4","expl":"Le FODEP du 30 avril est arrêté sur les comptes annuels au 31 décembre de l'année précédente.","exemple":"Les données annuelles clôturées fin décembre alimentent le FODEP d'avril."},
{"cat":"FODEP","q":"Sur quelle base est arrêté le FODEP transmis au 31 octobre ?","choices":["Les comptes annuels","Les états financiers intermédiaires arrêtés au 30 juin de l'année en cours","Les comptes prévisionnels du 4ème trimestre","Les comptes au 30 septembre"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 4","expl":"Le FODEP du 31 octobre est arrêté sur les états financiers intermédiaires au 30 juin de l'année en cours.","exemple":"Les comptes semestriels au 30/06 alimentent le FODEP d'octobre."},
{"cat":"FODEP","q":"Le FODEP s'applique sur base :","choices":["Individuelle uniquement","Individuelle (banques et EFCB), sous-consolidée (compagnies financières holding intermédiaires) et consolidée (EC maisons-mères et compagnies financières holding)","Consolidée uniquement","Au choix"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 2 (Champ d'application)","expl":"Le FODEP s'applique sur base individuelle (banques, EFCB), sous-consolidée (holdings intermédiaires) et consolidée (maisons-mères, holdings).","exemple":"Un groupe transmet un FODEP à chaque niveau : filiale, sous-groupe, groupe."},
{"cat":"FODEP","q":"Par quel mode les EC transmettent-ils le FODEP à la BCEAO ?","choices":["Par courrier postal uniquement","Par l'intermédiaire de la plate-forme informatique dédiée à cet effet","Par fax","Par disquette informatique"],"answer":1,"source":"Instruction n°005-08-2017 BCEAO — Art. 5","expl":"Le FODEP est transmis via la plateforme informatique dédiée de la BCEAO.","exemple":"Le reporting se fait en ligne sur la plateforme, non par courrier papier."},
{"cat":"Définitions & gouvernance","q":"Le dispositif prudentiel UMOA s'applique sur quelles bases ?","choices":["Individuelle uniquement","Individuelle (banques et EFCB), sous-consolidée (compagnies financières holding intermédiaires), consolidée (EC maisons-mères et compagnies financières holding)","Consolidée uniquement","Au choix de l'établissement"],"answer":1,"source":"Annexe Décision 013/2016 — §2 (Champ d'application)","expl":"Le dispositif prudentiel s'applique sur base individuelle, sous-consolidée et consolidée.","exemple":"Une banque respecte les ratios à son niveau propre et, si elle appartient à un groupe, au niveau consolidé."},
{"cat":"Définitions & gouvernance","q":"Qu'entend-on par « établissement de crédit maison-mère » ?","choices":["Toute banque mère","Un EC qui n'est pas contrôlé par un autre EC ou compagnie financière, ET qui détient au moins une filiale qui est un autre EC","Une compagnie d'assurance","Une banque centrale"],"answer":1,"source":"Annexe Décision 013/2016 — §1(g) + Décision 014/2016 — Art. 1(i)","expl":"Un EC maison-mère est un EC non contrôlé par un autre EC/compagnie financière et détenant au moins une filiale qui est elle-même un EC.","exemple":"Une banque sénégalaise détenant des filiales bancaires dans d'autres pays UEMOA est une maison-mère."},
{"cat":"Définitions & gouvernance","q":"La situation des succursales d'un établissement de crédit doit être :","choices":["Traitée séparément","Intégrée à celle de l'établissement qui en est propriétaire (pas de personnalité juridique distincte)","Soumise à un agrément séparé","Exclue du périmètre prudentiel"],"answer":1,"source":"Annexe Décision 013/2016 — §2 (Traitement des succursales)","expl":"La situation des succursales est intégrée à celle de l'établissement propriétaire, la succursale n'ayant pas de personnalité juridique distincte.","exemple":"Les risques d'une succursale sont agrégés à ceux du siège pour le calcul des ratios."},
{"cat":"Définitions & gouvernance","q":"Quel est le rôle de la Commission Bancaire de l'UMOA dans le dispositif prudentiel ?","choices":["Émettre la monnaie","Autorité de supervision : injonctions de mise en conformité, sanctions, agrément des dirigeants, supervision consolidée","Fixer les taux directeurs","Gérer les réserves de change"],"answer":1,"source":"Annexe Décision 013/2016 + Décision 014/2016","expl":"La CB-UMOA est l'autorité de supervision : injonctions, sanctions, agrément des dirigeants, supervision consolidée.","exemple":"Elle contrôle les banques, agrée leurs dirigeants et sanctionne les manquements prudentiels."}
];
module.exports = { QB };
